<?php
if(!isset($privoraBuild)){
    $privoraBuild=trim((string)@file_get_contents(dirname(__DIR__,2).'/VERSION'));
    if(!preg_match('/^5\.0\.0-dev\.(?:6\.[0-9]+|7\.0)$/',$privoraBuild))$privoraBuild='5.0.0-dev.7.0';
}
$privoraAssetVersion=rawurlencode($privoraBuild.'-mail-r2-config-r3-subroot-r1-imap-r1-mailcfg-r2-authdel-r2-ux700-dbowner-r1');
$privoraBuildLabel='DEV '.(string)preg_replace('/^5\.0\.0-dev\./','',$privoraBuild);
$adminPanelPort=(int)(getenv('PRIVORA_ADMIN_PANEL_PORT') ?: 8443);
$hostingPanelPort=(int)(getenv('PRIVORA_HOSTING_PANEL_PORT') ?: 2443);
$panelHost=(string)($_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'localhost');
if (preg_match('/^\[([^]]+)\](?::\d+)?$/',$panelHost,$m)) { $panelHost='['.$m[1].']'; }
else { $panelHost=(string)preg_replace('/:\d+$/','',$panelHost); }
$hostingPanelUrl='https://'.$panelHost.':'.$hostingPanelPort.'/';
$hostingPanelPathUrl='https://'.$panelHost.'/ppanel';
$commandCenterPathUrl='https://'.$panelHost.'/pcc';
?>
