e"></div></article><article class="panel-card wide"><h3>Webhooks</h3><div id="advWebhookTable" class="data-table"></div></article><article class="panel-card wide"><h3>Plugin registry</h3><div id="advPluginTable" class="data-table"></div></article></div></section>
<section class="page" data-view="cluster"><div class="page-head"><div><span class="eyebrow">MULTI-SERVER DNS</span><h2>DNS Clustering & Multi-Server</h2><p>Define authoritative DNS clusters and node roles. Live zone replication remains explicitly gated until remote nodes are enrolled and authenticated.</p></div></div><div class="split-page"><form class="panel-card quick-form" data-create="cluster-create"><h3>Create DNS cluster</h3><label>Name<input name="name" required value="authoritative-dns"></label><label>Nodes<input name="nodes" required placeholder="dns01,dns02"></label><label>Mode<select name="mode"><option>active-active</option><option>primary-secondary</option></select></label><input type="hidden" name="kind" value="dns"><button class="primary">Save cluster contract</button></form><article class="panel-card"><div id="advClusterTable" class="data-table"></div></article></div></section>
<section class="page" data-view="platform"><div class="page-head"><div><span class="eyebrow">PLATFORM ENGINEERING</span><h2>Platform engineering</h2><p>Migrations, clusters, HA contracts, extensions, billing integrations, recovery and release engineering.</p></div><span class="badge warning">EXTERNAL BACKENDS GATED</span></div>
<div class="split-page"><form class="panel-card quick-form" data-create="api-key-create"><h3>External API key</h3><label>Name<input name="name" required value="automation-client"></label><label>Scopes<input name="scopes" required value="health.read,accounts.read,sites.read"></label><button class="primary">Issue key</button><small class="muted">The secret is returned once; only its digest is stored by the agent.</small></form><article class="panel-card"><h3>API credentials</h3><div id="platformApiKeyTable" class="data-table"></div></article></div>
<div class="split-page"><form class="panel-card quick-form" data-create="migration-create"><h3>Migration plan</h3><label>Source type<select name="source_type"><option>cpanel</option><option>privora</option><option>directadmin</option><option>plesk</option><option>generic</option></select></label><label>Source<input name="source" required value="cpanel-source.example.test"></label><label>Account<input name="account" required value="acmeweb"></label><label>Destination<input name="destination" required value="privora-local"></label><button class="primary">Create migration plan</button></form><article class="panel-card"><div id="platformMigrationTable" class="data-table"></div></article></div>
<div class="grid"><article class="panel-card wide"><h3>Host adapter certification</h3><p class="muted">Detected dependencies and which local host adapters have passed executable certification.</p><div id="platformHostCapabilityTable" class="data-table"></div></article><article class="panel-card wide"><h3>Cluster & HA contracts</h3><div id="platformClusterTable" class="data-table"></div></article><article class="panel-card"><h3>Extensions</h3><div id="platformPluginTable" class="data-table"></div></article><article class="panel-card"><h3>Billing contracts</h3><div id="advInvoiceTable" class="data-table"></div></article><article class="panel-card wide"><h3>Diagnostics & recovery</h3><div id="advRecoveryTable" class="data-table"></div></article><article class="panel-card wide"><h3>Release & certification</h3><div id="advCertificationTable" class="data-table"></div></article></div>
<div class="platform-lab-section"><div class="page-head compact-head"><div><span class="eyebrow">SIMULATION LABS</span><h3>Fleet, cloud, automation & fabric</h3><p>Future multi-server contracts are consolidated here so experimental controls do not clutter primary server navigation.</p></div><span class="status-pill sim">SIMULATION / GATED</span></div><div class="platform-lab-grid"><article class="panel-card"><h3>Fleet node</h3><form class="quick-form compact-form" data-create="node-create"><label>Name<input name="name" required value="node01"></label><label>Role<select name="role"><option>web</option><option>dns</option><option>mail</option><option>database</option></select></label><label>Region<input name="region" required value="us-central"></label><label>Endpoint<input name="endpoint" type="url" required value="https://node01.example.test"></label><button class="primary">Add simulation node</button></form><div id="fleetTable" class="data-table compact-table"></div></article><article class="panel-card"><h3>Cloud instance</h3><form class="quick-form compact-form" data-create="instance-create"><label>Region<input name="region" required value="us-central"></label><label>Size<input name="size" required value="small"></label><label>Image<input name="image" required value="ubuntu-lts"></label><button class="primary">Create simulation instance</button></form><div id="cloudTable" class="data-table compact-table"></div></article><article class="panel-card"><h3>Provisioning automation</h3><form class="quick-form compact-form" data-create="automation-provision"><label>Customer<input name="customer" required value="Example Customer"></label><label>Username<input name="username" required value="exampleweb"></label><label>Domain<input name="domain" required value="example.test"></label><label>Package<input name="package" required value="Starter"></label><label>PHP<input name="php_version" required value="8.4"></label><button class="primary">Simulate provisioning</button></form><div id="automationTable" class="data-table compact-table"></div></article><article class="panel-card"><h3>Fabric workload</h3><form class="quick-form compact-form" data-create="workload-create"><label>Name<input name="name" required value="web-tier"></label><label>Type<select name="type"><option>web</option><option>worker</option><option>database</option></select></label><label>Region<input name="region" required value="us-central"></label><label>Desired replicas<input name="desired_replicas" type="number" min="1" max="64" value="2"></label><button class="primary">Create simulation workload</button></form><div id="fabricTable" class="data-table compact-table"></div></article></div></div>
</section>

</main></div>
<div class="modal" id="accountModal" aria-hidden="true"><form class="modal-card" id="accountForm"><button type="button" class="modal-close">×</button><span class="eyebrow">NEW HOSTING ACCOUNT</span><h3>Create account</h3><label>Username<input name="username" pattern="[a-z][a-z0-9_]{2,23}" required placeholder="acmeweb"></label><label>Primary domain<input name="primary_domain" required placeholder="example.com"></label><label>Package<select name="package" id="accountCreatePackage"></select></label><label>Reseller ownership<select name="reseller" id="accountCreateReseller"><option value="">Root administrator</option></select></label><label>Administrative owner<input name="owner" value="root" maxlength="64"></label><button class="primary">Provision account</button></form></div>

<div class="modal" id="ppanelAccessModal" aria-hidden="true"><form class="modal-card professional-form" id="ppanelAccessForm"><button type="button" class="modal-close">×</button><span class="eyebrow">PPANEL ACCESS</span><h3>Set Privora Panel login</h3><p class="muted">Choose a customer-facing PPanel username. The primary domain also remains a login alias; the underlying Linux account name is not required.</p><input type="hidden" name="account" id="ppanelAccessAccount"><input type="hidden" name="primary_domain" id="ppanelAccessDomain"><label>PPanel username<input name="panel_username" id="ppanelAccessLogin" minlength="3" maxlength="64" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,63}" autocomplete="username" required placeholder="customername"><small>3-64 characters: letters, numbers, dot, underscore or hyphen. This is independent from the Linux hosting username.</small></label><label>Primary-domain login alias<input id="ppanelAccessAlias" readonly><small>Customers can also sign in using the primary domain.</small></label><label>New password<input name="password" type="password" minlength="12" autocomplete="new-password" required placeholder="At least 12 characters"><small>This sets or resets the PPanel password for the hosting account.</small></label><button class="primary" type="submit">Save PPanel access</button></form></div>
<div class="modal" id="accountEditModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="accountEditForm"><button type="button" class="modal-close">×</button><span class="eyebrow">HOSTING ACCOUNT</span><h3>Edit <span id="accountEditLabel"></span></h3><input type="hidden" name="username" id="accountEditUsername"><div class="field-grid"><label>Primary domain<input name="primary_domain" required></label><label>Owner<input name="owner" maxlength="64"></label><label>Reseller<select name="reseller" id="accountEditReseller"><option value="">Root administrator</option></select></label><label>Shell access<select name="shell_policy"><option value="none">Disabled / nologin</option><option value="restricted">Restricted shell</option><option value="ssh">SSH shell</option></select></label></div><label>Account notes<textarea name="notes" maxlength="4096" rows="4"></textarea></label><div class="form-footer"><button class="primary" type="submit">Save account</button><button class="ghost" type="button" id="accountPasswordButton">Reset password</button></div><div id="accountHealthPanel" class="termination-plan"></div><div id="accountHistoryPanel" class="data-table"></div></form></div><div class="modal" id="accountPasswordModal" aria-hidden="true"><form class="modal-card" id="accountPasswordForm"><button type="button" class="modal-close">×</button><span class="eyebrow">ACCOUNT CREDENTIAL</span><h3>Reset Linux/SFTP password</h3><input type="hidden" name="username" id="accountPasswordUsername"><label>New password<input type="password" name="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="password_confirm" minlength="12" maxlength="1024" required autocomplete="new-password"></label><p class="muted">The plaintext password is sent once to the local privileged Agent through its authenticated Unix socket and is never persisted by Privora.</p><button class="danger" type="submit">Reset password</button></form></div><div class="modal" id="accountDeleteModal" aria-hidden="true"><form class="modal-card modal-card-wide" id="accountDeleteForm"><button type="button" class="modal-close">×</button><span class="eyebrow">ACCOUNT TERMINATION PREFLIGHT</span><h3>Terminate <span id="accountDeleteLabel"></span></h3><input type="hidden" name="username" id="accountDeleteUsername"><input type="hidden" name="plan_fingerprint" id="accountDeletePlanFingerprint"><p class="muted">Privora re-reads live ownership before termination. Known resources that cannot be removed safely block deletion instead of being orphaned.</p><div id="accountTerminationPlan" class="termination-plan"><div class="empty">Loading live termination plan…</div></div><label class="check-row"><input type="checkbox" name="delete_dns" checked> Remove Privora-managed DNS zones for owned websites</label><label>Type the account username to confirm<input name="confirm_username" id="accountDeleteConfirm" autocomplete="off" required></label><button class="danger destructive-primary" type="submit" disabled>Terminate suspended account</button></form></div>
<div class="modal" id="siteModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="siteForm"><button type="button" class="modal-close">×</button><div class="form-hero"><div><span class="eyebrow">WEBSITE PROVISIONING</span><h2>Create Website</h2><p id="siteAccountHint">Privora will provision the web root, Nginx vhost, PHP runtime and managed DNS integration using the detected server environment.</p></div><span class="status-pill active">GUIDED SETUP</span></div><section class="form-section"><div class="form-section-head"><span class="step-badge">1</span><div><h3>Website identity</h3><p>Enter the public domain that will serve this website.</p></div></div><div class="field-grid one"><label>Domain name<input name="domain" id="siteDomain" required inputmode="url" autocomplete="off" placeholder="example.com"><small>Use the exact hostname visitors should open. For a child site, use Add subdomain instead.</small></label></div></section><section class="form-section"><div class="form-section-head"><span class="step-badge">2</span><div><h3>Hosting & runtime</h3><p>Choose where the site belongs and which installed PHP-FPM runtime it should use.</p></div></div><div class="field-grid"><label id="siteOwnerField">Hosting account<select name="username" id="siteAccount"></select><small id="siteOwnerHelp">Privora will select an unambiguous detected owner automatically.</small></label><label>PHP runtime<select name="php_version" id="sitePhpVersion"><option>8.5</option><option selected>8.4</option><option>8.3</option><option>8.2</option></select><small>Only installed/certified runtimes will remain available after host discovery.</small></label></div></section><section class="form-section form-section-soft"><div class="form-section-head"><span class="step-badge">3</span><div><h3>Provisioning summary</h3><p>Privora uses safe automatic defaults for settings that do not require operator input.</p></div></div><div class="provision-summary"><div><span>Document root</span><b id="siteDocumentRootPreview">Automatic under hosting account</b></div><div><span>Web server</span><b>Nginx managed vhost</b></div><div><span>DNS</span><b>Managed automatically when local DNS owns the zone</b></div><div><span>SSL</span><b>Eligible for AutoSSL after DNS resolves</b></div></div><details class="advanced-disclosure"><summary>Advanced provisioning details</summary><p>A hosting package is not required to add a website. If there is no existing eligible owner, Privora can create a dedicated website owner according to the certified host adapter.</p></details></section><div class="form-footer"><button type="button" class="ghost modal-cancel">Cancel</button><button class="primary" type="submit">Create website</button></div></form></div>
<div class="modal" id="subdomainModal" aria-hidden="true"><form class="modal-card" id="subdomainForm"><button type="button" class="modal-close">×</button><span class="eyebrow">NEW SUBDOMAIN</span><h3>Create subdomain</h3><p class="muted">Privora creates a separate website vhost and adds A/AAAA records inside the managed parent DNS zone when available. The document root can be dedicated or shared with the parent website.</p><label>Subdomain name<div class="subdomain-builder"><input name="label" id="subdomainLabel" required autocomplete="off" inputmode="url" maxlength="63" pattern="[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?" placeholder="blog" aria-label="Subdomain name"><span class="subdomain-dot" aria-hidden="true">.</span><select name="parent_domain" id="subdomainParent" required aria-label="Existing domain"></select></div><small>Enter only the subdomain name. Choose the existing domain it belongs to.</small></label><div class="subdomain-preview">Will create: <b id="subdomainPreview">—</b></div><label>Document root<input name="document_root" id="subdomainDocumentRoot" required autocomplete="off" spellcheck="false" maxlength="512" placeholder="/home/account/domains/blog.example.com/public"><small id="subdomainRootHint">Privora will fill the dedicated default root automatically. You can change it or point the subdomain at the parent website root.</small></label><div class="subdomain-root-actions"><button type="button" class="ghost" id="subdomainUseDefaultRoot">Use default root</button><button type="button" class="ghost" id="subdomainUseParentRoot">Use parent domain root</button></div><label>PHP version<select name="php_version"><option>8.5</option><option selected>8.4</option><option>8.3</option><option>8.2</option></select></label><button class="primary" type="submit">Create subdomain</button></form></div>
<div class="modal" id="siteEditModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="siteEditForm"><button type="button" class="modal-close">×</button><div class="form-hero"><div><span class="eyebrow">WEBSITE SETTINGS</span><h2 id="siteEditTitle">Edit Website</h2><p>Manage safe per-site settings without exposing the underlying Linux account identity.</p></div><span class="status-pill" id="siteEditStatus">Checking</span></div><input type="hidden" name="domain" id="siteEditDomain"><section class="form-section"><div class="field-grid"><label>Domain<input id="siteEditDomainDisplay" readonly></label><label>Hosting account<input id="siteEditAccount" readonly></label><label>Document root<input id="siteEditRoot" readonly></label><label>PHP runtime<select name="version" id="siteEditPhp"></select></label></div></section><section class="form-section form-section-soft"><div class="provision-summary"><div><span>DNS</span><b id="siteEditDNS">—</b></div><div><span>SSL</span><b id="siteEditSSL">—</b></div><div><span>Type</span><b id="siteEditKind">Website</b></div><div><span>Detection</span><b id="siteEditDetection">—</b></div></div></section><div class="form-footer site-edit-actions"><button type="button" class="ghost" id="siteEditOpen">Open website</button><button type="button" class="ghost" id="siteEditDNSOpen">Manage DNS</button><button type="button" class="ghost" id="siteEditAutoSSL">Run AutoSSL</button><button class="primary" type="submit">Save website settings</button></div></form></div><div class="modal" id="siteDeleteModal" aria-hidden="true"><form class="modal-card" id="siteDeleteForm"><button type="button" class="modal-close">×</button><span class="eyebrow">DELETE WEBSITE</span><h3>Remove <span id="siteDeleteDomainLabel"></span></h3><input type="hidden" name="domain" id="siteDeleteDomain"><p class="muted" id="siteDeleteDescription">The website vhost will be removed. Website files are preserved unless you explicitly choose to delete them.</p><label class="check-row"><input type="checkbox" name="delete_dns" checked> Remove Privora-managed DNS zone</label><label class="check-row"><input type="checkbox" name="delete_files"> <span id="siteDeleteFilesLabel">Permanently delete website files</span></label><button class="danger" type="submit">Delete website</button></form></div>
<div class="modal" id="registrarConnectModal" aria-hidden="true"><form class="modal-card professional-form" id="registrarConnectForm"><button type="button" class="modal-close">×</button><span class="eyebrow">REGISTRAR CONNECTION</span><h3>Connect Registrar</h3><p class="muted">Connect a Privora-compatible registrar adapter so registry glue and delegation can be synchronized from the control panel.</p><label>Provider<input name="provider" required maxlength="64" placeholder="Hostinger, Namecheap, Cloudflare Registrar…"></label><label>Adapter URL<input name="adapter_url" type="url" required placeholder="https://registrar-adapter.example.com"></label><label>API token<input name="token" type="password" required autocomplete="new-password" placeholder="Registrar adapter token"><small>The token is sent only to the local Privora Agent and is never displayed back in the panel.</small></label><input type="hidden" name="base_domain" id="registrarConnectDomain"><button class="primary" type="submit">Save & connect</button></form></div>
<div class="modal" id="nameserverManualModal" aria-hidden="true"><div class="modal-card modal-card-wide"><button type="button" class="modal-close">×</button><span class="eyebrow">MANUAL REGISTRAR SETUP</span><h3>Nameserver Setup Instructions</h3><p class="muted">Complete these steps at the registrar that owns the base domain. Privora will keep checking public DNS and update the status automatically.</p><div id="nameserverManualInstructions" class="manual-ns-instructions"></div><div class="form-footer"><button type="button" class="primary modal-close">Done</button></div></div></div>
<div class="modal command-modal" id="commandModal" aria-hidden="true"><div class="modal-card command-card"><button type="button" class="modal-close">×</button><span class="eyebrow">COMMAND PALETTE</span><h3>Find a Privora control</h3><input id="commandSearch" autocomplete="off" placeholder="Try: accounts, PHP, security, migrations…"><div id="commandResults" class="command-results"></div><small>Navigation only in this development gate. Privileged mutations still require their normal confirmation path.</small></div></div>
<div class="modal" id="databaseEditModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="databaseEditForm"><button type="button" class="modal-close">×</button><div class="form-hero"><div><span class="eyebrow">DATABASE ACCESS</span><h2>Edit database access</h2><p>Change the paired database username and/or set a new password. Database names are not renamed by this safety-gated editor.</p></div><span class="status-pill active">MANAGED</span></div><section class="form-section"><input type="hidden" name="name"><div class="field-grid"><label>Database<input name="database_display" readonly></label><label>Engine<input name="engine_display" readonly></label><label>Database user<input name="user" required autocomplete="username"></label><label>New password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" placeholder="Leave blank to generate if user changes"></label><label>Confirm password<input name="password_confirm" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label></div><button type="button" class="ghost" data-db-generate="admin-edit">Generate password</button></section><div class="form-footer"><button type="button" class="ghost modal-cancel">Cancel</button><button class="primary" type="submit">Save database access</button></div></form></div><div class="modal" id="resellerAccessModal" aria-hidden="true"><form class="modal-card" id="resellerAccessForm"><button type="button" class="modal-close">×</button><span class="eyebrow">RESELLER ACCESS</span><h3>Configure delegated PCC login</h3><input type="hidden" name="name" id="resellerAccessName"><label>Panel username<input name="login" id="resellerAccessLogin" minlength="3" maxlength="64" required autocomplete="username"></label><label>New password<input type="password" name="password" minlength="12" maxlength="1024" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="password_confirm" minlength="12" maxlength="1024" required autocomplete="new-password"></label><p class="muted">The password is stored only as a password hash. This login is bound to the selected reseller scope and cannot access another reseller's accounts.</p><button class="primary" type="submit">Save reseller access</button></form></div><div class="modal" id="customCertificateModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="customCertificateForm"><button type="button" class="modal-close">×</button><span class="eyebrow">CUSTOM TLS</span><h3>Install custom certificate</h3><input type="hidden" name="domain" id="customCertificateDomain"><label>Certificate / full chain PEM<textarea name="certificate" rows="10" required placeholder="-----BEGIN CERTIFICATE-----"></textarea></label><label>Private key PEM<textarea name="private_key" rows="8" required placeholder="-----BEGIN PRIVATE KEY-----"></textarea></label><p class="muted">Privora validates the PEM, hostname coverage, expiry and public-key match before changing Nginx. The private key is written mode 0600 and is never logged.</p><button class="primary" type="submit">Validate &amp; install</button></form></div><div class="modal" id="mailboxEditModal" aria-hidden="true"><form class="modal-card modal-card-wide professional-form" id="mailboxEditForm"><button type="button" class="modal-close">×</button><div class="form-hero"><div><span class="eyebrow">EMAIL ACCOUNT</span><h2>Edit mailbox</h2><p>Change quota and optionally reset the password without renaming the mailbox or replacing its Maildir.</p></div><span class="status-pill active">LIVE MAILBOX</span></div><section class="form-section"><input type="hidden" name="address"><div class="field-grid"><label>Email address<input name="address_display" readonly></label><label>Quota (MB)<input name="quota_mb" type="number" min="100" max="102400" required></label><label>New password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" placeholder="Leave blank to keep current password"></label><label>Confirm new password<input name="password_confirm" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label></div><button type="button" class="ghost" data-mail-password-generate="admin-edit">Generate strong password</button></section><div class="form-footer"><button type="button" class="ghost modal-cancel">Cancel</button><button class="primary" type="submit">Save email account</button></div></form></div><div class="modal" id="mailAliasEditModal" aria-hidden="true"><form class="modal-card professional-form" id="mailAliasEditForm"><button type="button" class="modal-close">×</button><span class="eyebrow">FORWARDER</span><h2>Edit forwarder</h2><p class="muted">Change the delivery destination while keeping the forwarder address unchanged.</p><input type="hidden" name="address"><label>Forwarder address<input name="address_display" readonly></label><label>Deliver to<input name="destination" type="email" required></label><div class="form-footer"><button type="button" class="ghost modal-cancel">Cancel</button><button class="primary" type="submit">Save forwarder</button></div></form></div><div class="modal" id="mailDomainManageModal" aria-hidden="true"><div class="modal-card modal-card-wide professional-form"><button type="button" class="modal-close">×</button><div class="form-hero"><div><span class="eyebrow">LIVE MAIL CONFIGURATION</span><h2 id="mailDomainManageTitle">Mail client setup</h2><p>Read directly from the server's Postfix, Dovecot, TLS and listener configuration.</p></div><span class="status-pill" id="mailDomainManageBadge">CHECKING</span></div><div id="mailDomainManageStatus" class="mail-domain-live-status muted">Reading live mail configuration…</div><div id="mailDomainManageServices" class="mail-client-services"></div><article class="mail-client-copy-card"><div class="card-head"><div><h3>Mail account setup instructions</h3><small>Copy these settings into Outlook, Thunderbird, Apple Mail, Android or another mail client.</small></div><button type="button" class="ghost" id="mailDomainConfigCopy">Copy settings</button></div><pre id="mailDomainConfigText"></pre></article><div class="form-footer"><button type="button" class="ghost" id="mailDomainConfigRefresh">Refresh from server</button><button type="button" class="primary modal-close">Done</button></div></div></div><div class="toast" id="toast"></div><script src="/assets/app.js?v=<?=$privoraAssetVersion?>"></script><script src="/assets/components.js?v=<?=$privoraAssetVersion?>"></script><script src="/assets/v7-admin.js?v=<?=$privoraAssetVersion?>"></script></body></html>
